-- The Commitment record (Wave 6, OP:115; SPINE-CONTRACT 1.1; OPUS decision 9).
--
-- The name sorts after 20261010235900_tenant_rls, so the tenant tables created
-- here are policed by this file itself (rlsMigrationOrder.test.ts checks that).
-- The CREATE TABLE and index statements are generated by `prisma migrate diff`;
-- everything below the line of hand-written SQL is an invariant Prisma cannot
-- express, and each one must hold for every writer, not only for the domain.

-- CreateTable
CREATE TABLE "commitments" (
    "id" TEXT NOT NULL,
    "tenantId" TEXT NOT NULL,
    "recordCode" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "nextAction" TEXT,
    "ownerPartyId" TEXT NOT NULL,
    "backupPartyId" TEXT,
    "dueAt" TIMESTAMP(3) NOT NULL,
    "state" TEXT NOT NULL DEFAULT 'proposed',
    "sourceType" TEXT NOT NULL,
    "sourceId" TEXT,
    "confirmedById" TEXT,
    "confirmedAt" TIMESTAMP(3),
    "subjectType" TEXT NOT NULL,
    "subjectId" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "commitments_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "commitment_events" (
    "id" TEXT NOT NULL,
    "tenantId" TEXT NOT NULL,
    "commitmentId" TEXT NOT NULL,
    "fromState" TEXT,
    "toState" TEXT NOT NULL,
    "actorPartyId" TEXT,
    "reason" TEXT,
    "at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "commitment_events_pkey" PRIMARY KEY ("id")
);

