ALTER TABLE "commitments" ADD CONSTRAINT "commitments_tenantId_ownerPartyId_fkey" FOREIGN KEY ("tenantId", "ownerPartyId") REFERENCES "people"("tenantId", "id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "commitments" ADD CONSTRAINT "commitments_tenantId_backupPartyId_fkey" FOREIGN KEY ("tenantId", "backupPartyId") REFERENCES "people"("tenantId", "id") ON DELETE RESTRICT ON UPDATE RESTRICT;

