ALTER TABLE "commitments" ADD CONSTRAINT "commitments_tenantId_confirmedById_fkey" FOREIGN KEY ("tenantId", "confirmedById") REFERENCES "people"("tenantId", "id") ON DELETE RESTRICT ON UPDATE RESTRICT;

