ALTER TABLE "commitment_events" ADD CONSTRAINT "commitment_events_tenantId_actorPartyId_fkey" FOREIGN KEY ("tenantId", "actorPartyId") REFERENCES "people"("tenantId", "id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- ---------------------------------------------------------------------------
-- Hand-written from here down.
-- ---------------------------------------------------------------------------

-- 1. The state list is closed. A new state is a migration, because the
--    transition table in domains/commitments.ts and this list must change together.
ALTER TABLE "commitments"
  ADD CONSTRAINT "commitments_state_known"
  CHECK ("state" IN ('proposed', 'confirmed', 'met', 'missed', 'cancelled'));

ALTER TABLE "commitment_events"
  ADD CONSTRAINT "commitment_events_to_state_known"
  CHECK ("toState" IN ('proposed', 'confirmed', 'met', 'missed', 'cancelled'));

ALTER TABLE "commitment_events"
  ADD CONSTRAINT "commitment_events_from_state_known"
  CHECK ("fromState" IS NULL OR "fromState" IN ('proposed', 'confirmed', 'met', 'missed', 'cancelled'));

-- 2. The backup is never the owner. The domain refuses it with a 422 first; this
--    is the floor for a writer that goes around the domain.
ALTER TABLE "commitments"
  ADD CONSTRAINT "commitments_backup_not_owner"
  CHECK ("backupPartyId" IS NULL OR "backupPartyId" <> "ownerPartyId");

-- 3. A commitment that has been confirmed records who confirmed it and when.
--    Silence never confirms: a proposed row has neither, and no path fills them
--    in without the human confirmation that sets both together.
ALTER TABLE "commitments"
  ADD CONSTRAINT "commitments_confirmation_recorded"
  CHECK (("confirmedById" IS NULL) = ("confirmedAt" IS NULL));

ALTER TABLE "commitments"
  ADD CONSTRAINT "commitments_confirmed_states_have_confirmer"
  CHECK ("state" NOT IN ('confirmed', 'met', 'missed') OR "confirmedAt" IS NOT NULL);

-- 4. The history is append-only. No application path updates or deletes a row
--    (the domain writes one per change), so the trigger refuses both for every
--    role, the table owner included. A correction is a new row.
CREATE OR REPLACE FUNCTION "commitment_events_immutable"()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'commitment events are immutable; a correction is a new event'
    USING ERRCODE = 'check_violation';
END
$$;

CREATE TRIGGER "commitment_events_immutable"
  BEFORE UPDATE OR DELETE ON "commitment_events"
  FOR EACH ROW EXECUTE FUNCTION "commitment_events_immutable"();

-- 5. Row-level security on the new tables. Written out, not looped, so that the
--    migration is correct on its own and rlsMigrationOrder.test.ts can read it.
ALTER TABLE "commitments" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "commitments" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "tenant_isolation" ON "commitments";
CREATE POLICY "tenant_isolation" ON "commitments"
  USING ("tenantId" = current_setting('app.tenant_id', true))
  WITH CHECK ("tenantId" = current_setting('app.tenant_id', true));

ALTER TABLE "commitment_events" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "commitment_events" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "tenant_isolation" ON "commitment_events";
CREATE POLICY "tenant_isolation" ON "commitment_events"
  USING ("tenantId" = current_setting('app.tenant_id', true))
  WITH CHECK ("tenantId" = current_setting('app.tenant_id', true));

-- 6. The application role may use the new tables. Guarded, as in
--    20261010235800_business_lines: on a fresh database the role is created by
--    tenant_rls, which grants on every table anyway.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'kaizen_app') THEN
    GRANT SELECT, INSERT, UPDATE, DELETE ON "commitments" TO "kaizen_app";
    GRANT SELECT, INSERT ON "commitment_events" TO "kaizen_app";
  END IF;
END
$$;
